// Shared behaviour for every page. Data comes from data.js (generated by build.py).
(() => {
  const D = window.DAVIAS;
  const STONES = D.stones;

  // ---------- Bead strand illustration ----------
  function strand(stones, n = 13) {
    const w = 520, h = 80, r = 17, gap = (w - 2 * r) / (n - 1);
    let beads = "";
    for (let i = 0; i < n; i++) {
      const s = STONES[stones[i % stones.length]];
      const c = s.colors[i % s.colors.length];
      const x = r + i * gap, y = h / 2 + Math.sin(i / (n - 1) * Math.PI) * 10 - 5;
      beads += `<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>` +
        `<circle cx="${x - r * .35}" cy="${y - r * .4}" r="${r * .3}" fill="#fff" opacity=".35"/>`;
    }
    return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${stones.map(k => STONES[k].name).join(", ")} beads">` +
      `<path d="M0 ${h / 2} Q ${w / 2} ${h / 2 + 22} ${w} ${h / 2}" stroke="#d8b468" stroke-opacity=".5" fill="none"/>${beads}</svg>`;
  }
  document.querySelectorAll("[data-strand]").forEach(el => {
    el.innerHTML = strand(el.dataset.strand.split(","), +(el.dataset.n || 13));
  });

  // ---------- Mobile menu ----------
  const menuBtn = document.querySelector(".menu-btn");
  const links = document.querySelector(".links");
  if (menuBtn && links) {
    menuBtn.addEventListener("click", () => {
      const open = links.classList.toggle("open");
      menuBtn.setAttribute("aria-expanded", open);
    });
  }

  // ---------- Order bag (kept in this browser only) ----------
  const KEY = "davias-bag";
  const readBag = () => { try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch { return []; } };
  const writeBag = b => { try { localStorage.setItem(KEY, JSON.stringify(b)); } catch {} updateCount(); };
  function updateCount() {
    document.querySelectorAll("[data-bag-count]").forEach(el => el.textContent = readBag().length);
  }
  updateCount();

  const addBtn = document.getElementById("add-to-bag");
  if (addBtn) {
    addBtn.addEventListener("click", () => {
      const size = document.getElementById("size");
      const bag = readBag();
      bag.push({ slug: addBtn.dataset.slug, size: size ? size.value : "" });
      writeBag(bag);
      document.getElementById("added").textContent = "Added to your order bag.";
    });
  }

  const bagList = document.getElementById("bag-list");
  if (bagList) {
    const msg = document.getElementById("order-message");
    const nameIn = document.getElementById("order-name");
    const noteIn = document.getElementById("order-note");
    function render() {
      const bag = readBag();
      const products = Object.fromEntries(D.products.map(p => [p.slug, p]));
      bagList.innerHTML = bag.length ? bag.map((it, i) => {
        const p = products[it.slug];
        if (!p) return "";
        return `<div class="bag-row"><div class="mini">${strand(p.stones, 7)}</div>` +
          `<div><b>${p.name}</b><div class="note">${D.types[p.type][0].replace(/s$/, "")} · ${it.size || "size to confirm"}</div></div>` +
          `<button data-i="${i}">Remove</button></div>`;
      }).join("") : `<p class="lede">Your bag is empty. <a href="shop.html">Browse the shop</a>.</p>`;
      const lines = bag.map(it => products[it.slug]).filter(Boolean)
        .map((p, i) => `- ${p.name} (${p.type}${bag[i].size ? ", " + bag[i].size : ""})`);
      msg.value =
        `Hi Davias! I'd like to order:\n${lines.join("\n") || "- (add pieces from the shop)"}\n\n` +
        (noteIn.value.trim() ? `Note: ${noteIn.value.trim()}\n\n` : "") +
        `Name: ${nameIn.value.trim() || "(your name)"}\nPlease confirm the price and shipping. Thank you!`;
      const mail = document.getElementById("order-email");
      mail.href = `mailto:${D.site.email}?subject=${encodeURIComponent("Davias order")}&body=${encodeURIComponent(msg.value)}`;
    }
    bagList.addEventListener("click", e => {
      const b = e.target.closest("button[data-i]");
      if (!b) return;
      const bag = readBag(); bag.splice(+b.dataset.i, 1); writeBag(bag); render();
    });
    [nameIn, noteIn].forEach(el => el.addEventListener("input", render));
    document.getElementById("copy-order").addEventListener("click", async () => {
      const status = document.getElementById("copy-status");
      try { await navigator.clipboard.writeText(msg.value); status.textContent = "Copied. Paste it into a DM or email."; }
      catch { msg.select(); status.textContent = "Select-all is on: copy it with Ctrl+C / long-press."; }
    });
    render();
  }

  // ---------- Shop filters ----------
  const filters = document.querySelector(".filters");
  if (filters) {
    filters.addEventListener("click", e => {
      const b = e.target.closest("button"); if (!b) return;
      filters.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b));
      const f = b.dataset.filter;
      document.querySelectorAll("#products .piece").forEach(card => {
        const show = f === "all" || card.dataset.type === f || card.dataset.stones.split(",").includes(f);
        card.hidden = !show;
      });
    });
    const want = location.hash.slice(1);
    const start = want && filters.querySelector(`[data-filter="${want}"]`);
    if (start) start.click();
  }

  // ---------- Stone guide ----------
  const list = document.getElementById("stone-list");
  if (list) {
    const detail = document.getElementById("stone-detail");
    function showStone(key) {
      const s = STONES[key];
      list.querySelectorAll("button").forEach(b => b.setAttribute("aria-selected", b.dataset.k === key));
      const on = Math.round(s.mohs);
      detail.innerHTML =
        `<div style="display:grid;gap:8px"><h3 style="font-size:40px">${s.name}</h3><div class="strand" style="height:60px">${strand([key], 13)}</div></div>` +
        `<div class="mohs"><span class="eyebrow">Hardness · Mohs ${s.mohs}</span>` +
        `<div class="bar">${Array.from({ length: 10 }, (_, i) => `<i class="${i < on ? "on" : ""}"></i>`).join("")}</div>` +
        `<div class="scale"><span>1 talc</span><span>2 fingernail</span><span>5.5 glass</span><span>7 quartz</span><span>10 diamond</span></div></div>` +
        `<div class="labels">` +
        `<div class="label proven"><h4>Proven</h4><p>${s.proven}</p></div>` +
        `<div class="label trad"><h4>Traditional</h4><p>${s.trad}</p></div>` +
        `<div class="label care"><h4>Care</h4><p>${s.care}</p></div>` +
        `<div class="label no"><h4>We never claim</h4><p>${s.no}</p></div></div>`;
    }
    list.innerHTML = Object.entries(STONES).map(([k, s]) =>
      `<button role="tab" data-k="${k}" aria-selected="false"><span class="dot" style="background:${s.colors[0]}"></span>${s.name}</button>`).join("");
    list.addEventListener("click", e => { const b = e.target.closest("button"); if (b) showStone(b.dataset.k); });
    const want = location.hash.slice(1);
    showStone(STONES[want] ? want : Object.keys(STONES)[0]);
  }

  // ---------- Crystal finder ----------
  const finder = document.getElementById("finder-form");
  if (finder) {
    const OPTS = {
      color: [["gold", "Warm gold", ["quartz", "tiger"]], ["purple", "Purple", ["pjade"]], ["green", "Green", ["gjade"]], ["white", "White & clear", ["clear", "selenite"]]],
      feel: [["calm", "Calm", ["pjade", "selenite"]], ["confidence", "Confidence", ["tiger"]], ["balance", "Balance", ["gjade"]], ["warmth", "Warmth & joy", ["quartz"]], ["clarity", "Clarity", ["clear", "selenite"]]],
      wear: [["every", "Every day, all day", []], ["gentle", "Special occasions", []]],
    };
    const pick = { color: new Set(["gold"]), feel: new Set(["confidence"]), wear: "every" };
    for (const [group, opts] of Object.entries(OPTS)) {
      const box = document.getElementById("opt-" + group);
      const type = group === "wear" ? "radio" : "checkbox";
      box.innerHTML = opts.map(([v, label]) => {
        const checked = group === "wear" ? pick.wear === v : pick[group].has(v);
        return `<label><input type="${type}" name="${group}" id="f-${group}-${v}" value="${v}" ${checked ? "checked" : ""}><span>${label}</span></label>`;
      }).join("");
    }
    finder.addEventListener("change", () => {
      pick.color = new Set([...finder.querySelectorAll("input[name=color]:checked")].map(i => i.value));
      pick.feel = new Set([...finder.querySelectorAll("input[name=feel]:checked")].map(i => i.value));
      pick.wear = (finder.querySelector("input[name=wear]:checked") || {}).value || "every";
      renderFinder();
    });
    function renderFinder() {
      const score = {};
      const add = (keys, w) => keys.forEach(k => score[k] = (score[k] || 0) + w);
      OPTS.color.forEach(([v, , keys]) => pick.color.has(v) && add(keys, 2));
      OPTS.feel.forEach(([v, , keys]) => pick.feel.has(v) && add(keys, 1));
      let ranked = Object.keys(score).sort((a, b) => score[b] - score[a]);
      const out = document.getElementById("finder-result");
      if (!ranked.length) {
        out.innerHTML = `<h3>Choose a color or a tradition</h3><p class="lede" style="font-size:15px">Your combination appears here.</p>`;
        return;
      }
      let warn = "";
      if (pick.wear === "every" && ranked.includes("selenite")) {
        ranked = ranked.filter(k => k !== "selenite").concat("selenite");
        warn = `<p class="note">For everyday wear, keep selenite as an accent: at Mohs 2 it scratches and dislikes water.</p>`;
      }
      const combo = ranked.slice(0, 2);
      // Pieces that already use these stones.
      const matches = D.products
        .map(p => [p, combo.filter(k => p.stones.includes(k)).length])
        .filter(([, n]) => n > 0).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([p]) => p);
      out.innerHTML =
        `<span class="eyebrow">Your combination</span><h3 style="font-size:34px">${combo.map(k => STONES[k].name).join(" + ")}</h3>` +
        `<div class="strand">${strand(combo, 13)}</div>` +
        `<ul>${combo.map(k => `<li><b style="color:var(--gold);font-weight:500">Proven:</b> ${STONES[k].proven}</li>` +
          `<li><b style="color:var(--lilac);font-weight:500">Traditional:</b> ${STONES[k].trad}</li>`).join("")}</ul>` + warn +
        (matches.length ? `<span class="eyebrow">Pieces with these stones</span><div class="chips">${matches.map(p =>
          `<a class="chip" href="p/${p.slug}.html">${p.name}</a>`).join("")}</div>` : "");
    }
    renderFinder();
  }

  // ---------- Drop list sign-up (opens an email; no server yet) ----------
  const join = document.getElementById("join");
  if (join) {
    join.addEventListener("submit", e => {
      e.preventDefault();
      const email = document.getElementById("join-email").value.trim();
      const href = `mailto:${D.site.email}?subject=${encodeURIComponent("Drop list")}&body=${encodeURIComponent("Please tell me when the next drop opens: " + email)}`;
      document.getElementById("join-msg").innerHTML =
        `Almost done: <a href="${href}">send this email</a> to join, or write to ${D.site.email} with "Drop list".`;
      location.href = href;
    });
  }

  // ---------- Hero: bead bracelet circling the logo ----------
  const cv = document.getElementById("orbit");
  if (cv) {
    const ctx = cv.getContext("2d");
    const ring = ["quartz", "pjade", "tiger", "gjade", "selenite", "quartz", "pjade", "tiger", "gjade", "clear", "pjade", "tiger", "gjade", "selenite", "tiger", "quartz"];
    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    function draw(t) {
      const dpr = window.devicePixelRatio || 1, size = cv.clientWidth;
      if (cv.width !== Math.round(size * dpr)) { cv.width = cv.height = Math.round(size * dpr); }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, size, size);
      const c = size / 2, R = size * 0.4, br = size * 0.042, rot = still ? 0 : t / 60000 * Math.PI * 2;
      ring.forEach((k, i) => {
        const a = rot + i / ring.length * Math.PI * 2;
        const x = c + Math.cos(a) * R, y = c + Math.sin(a) * R;
        const pulse = still ? .25 : .15 + .15 * Math.sin(t / 900 + i);
        ctx.strokeStyle = `rgba(216,180,104,${pulse})`;
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(c + Math.cos(a) * R * .55, c + Math.sin(a) * R * .55); ctx.stroke();
        const s = STONES[k], g = ctx.createRadialGradient(x - br * .4, y - br * .4, br * .1, x, y, br);
        g.addColorStop(0, "#ffffff"); g.addColorStop(.25, s.colors[0]); g.addColorStop(1, s.colors[2] || s.colors[1]);
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, br, 0, Math.PI * 2); ctx.fill();
      });
      if (!still) requestAnimationFrame(draw);
    }
    requestAnimationFrame(draw);
  }
})();
